name: Close Inactive Issues

on:
  schedule:
    - cron: '0 0 * * *'

jobs:
  close-issues:
    runs-on: ubuntu-latest

    steps:
      - uses: actions/github-script@v6
        with:
          script: |
            const { context } = github;
            const { owner, repo } = context.repo;
            const threshold = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

            const issues = await github.rest.issues.listForRepo({
              owner,
              repo,
              state: 'open',
              created_at: {
                lte: threshold.toISOString(),
              },
            });

            for (const issue of issues.data) {
              await github.rest.issues.update({
                owner,
                repo,
                issue_number: issue.number,
                state: 'closed',
              });
            }

on:
  issues:
    types: [assigned]

jobs:
  move-issue:
    runs-on: ubuntu-latest
    steps:
      - name: Move issue to project
        uses: actions/checkout@v2
      - name: Update project
        uses: actions/github-script@v6
        with:
          script: |
            const projectNumber = 1; // Replace with your project number
            const columnName = 'In Progress'; // Replace with your column name
            const issue = context.payload.issue;
            const project = await github.projects.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo
            }).then(res => res.data.find(p => p.number === projectNumber));
            if (!project) {
              throw new Error(`Project not found: ${projectNumber}`);
            }
            const columns = await github.projects.listColumns({
              project_id: project.id
            }).then(res => res.data);
            const column = columns.find(c => c.name === columnName);
            if (!column) {
              throw new Error(`Column not found: ${columnName}`);
            }
            await github.projects.createCard({
              column_id: column.id,
              content_id: issue.id,
              content_type: 'Issue'
            });

