name: Remove label when card added to project column
on:
  project_card:
    types: [created]
jobs:
  remove-label:
    runs-on: ubuntu-latest
    steps:
      - name: Remove label from issue
        uses: actions/github-script@v7
        with:
          script: |
            if (context.payload.project_card.content_url && context.payload.project_card.content_url.includes('/issues/')) {
              const issueUrl = context.payload.project_card.content_url;
              const issueNumber = issueUrl.split('/').pop();
              const owner = context.repo.owner;
              const repo = context.repo.repo;
              const labelToRemove = 'YOUR_LABEL_NAME';
              await github.rest.issues.removeLabel({
                owner,
                repo,
                issue_number: issueNumber,
                name: labelToRemove
              });
            }

